class Solution { public:int mostBooked(int n,vector<vector<int>>& meetings){sort(meetings.begin(),meetings.end());priority_queue<int,vector<int>,greater<int>> available;for(int room=0;room<n;++room)available.push(room);using State=pair<long long,int>;priority_queue<State,vector<State>,greater<State>> busy;vector<int> count(n);for(auto& meeting:meetings){long long start=meeting[0],duration=meeting[1]-meeting[0];while(!busy.empty()&&busy.top().first<=start){available.push(busy.top().second);busy.pop();}int room;long long end;if(!available.empty()){room=available.top();available.pop();end=start+duration;}else{auto state=busy.top();busy.pop();room=state.second;end=state.first+duration;}++count[room];busy.push({end,room});}return max_element(count.begin(),count.end())-count.begin();} };
